def check_password_strength(password: str) -> dict:
    if not password:
        return {'score': 0, 'strength': 'very_weak', 'suggestions': ['Password cannot be empty']}

    score = 0
    suggestions = []

    common = {'password', '123456', 'qwerty', 'admin', 'letmein', 'welcome', 'monkey', 'dragon', 'master', '123456789', '12345678', '1234567', '12345', '1234', '111111', 'abc123'}

    # Length
    if len(password) >= 8: score += 10
    else: suggestions.append('Use at least 8 characters')
    if len(password) >= 12: score += 10
    if len(password) >= 16: score += 10

    # Character types
    has_lower = any(c.islower() for c in password)
    has_upper = any(c.isupper() for c in password)
    has_digit = any(c.isdigit() for c in password)
    has_special = any(not c.isalnum() for c in password)

    if has_lower: score += 10
    else: suggestions.append('Add lowercase letters')
    if has_upper: score += 10
    else: suggestions.append('Add uppercase letters')
    if has_digit: score += 10
    else: suggestions.append('Add numbers')
    if has_special: score += 15
    else: suggestions.append('Add special characters')

    # No sequential (abc, 123)
    has_sequential = False
    for i in range(len(password) - 2):
        if ord(password[i+1]) - ord(password[i]) == 1 and ord(password[i+2]) - ord(password[i+1]) == 1:
            has_sequential = True
            break
        if ord(password[i]) - ord(password[i+1]) == 1 and ord(password[i+1]) - ord(password[i+2]) == 1:
            has_sequential = True
            break
    if not has_sequential: score += 10
    else: suggestions.append('Avoid sequential characters')

    # No repeating (aaa)
    has_repeat = False
    for i in range(len(password) - 2):
        if password[i] == password[i+1] == password[i+2]:
            has_repeat = True
            break
    if not has_repeat: score += 5
    else: suggestions.append('Avoid repeating characters')

    # Not common
    if password.lower() not in common: score += 10
    else: suggestions.append('Avoid common passwords')

    score = min(100, max(0, score))

    if score <= 25: strength = 'very_weak'
    elif score <= 50: strength = 'weak'
    elif score <= 70: strength = 'medium'
    elif score <= 90: strength = 'strong'
    else: strength = 'very_strong'

    return {'score': score, 'strength': strength, 'suggestions': suggestions}

