function checkPasswordStrength(password) {
  if (!password) return { score: 0, strength: 'very_weak', suggestions: ['Password cannot be empty'] };

  let score = 0;
  const suggestions = [];
  const common = new Set(['password','123456','qwerty','admin','letmein','welcome','monkey','dragon','master','123456789','12345678','1234567','12345','1234','111111','abc123']);

  if (password.length >= 8) score += 10; else suggestions.push('Use at least 8 characters');
  if (password.length >= 12) score += 10;
  if (password.length >= 16) score += 10;

  const hasLower = /[a-z]/.test(password);
  const hasUpper = /[A-Z]/.test(password);
  const hasDigit = /\d/.test(password);
  const hasSpecial = /[^a-zA-Z0-9]/.test(password);

  if (hasLower) score += 10; else suggestions.push('Add lowercase letters');
  if (hasUpper) score += 10; else suggestions.push('Add uppercase letters');
  if (hasDigit) score += 10; else suggestions.push('Add numbers');
  if (hasSpecial) score += 15; else suggestions.push('Add special characters');

  let hasSequential = false;
  for (let i = 0; i < password.length - 2; i++) {
    const d1 = password.charCodeAt(i+1) - password.charCodeAt(i);
    const d2 = password.charCodeAt(i+2) - password.charCodeAt(i+1);
    if ((d1 === 1 && d2 === 1) || (d1 === -1 && d2 === -1)) { hasSequential = true; break; }
  }
  if (!hasSequential) score += 10; else suggestions.push('Avoid sequential characters');

  let hasRepeat = false;
  for (let i = 0; i < password.length - 2; i++) {
    if (password[i] === password[i+1] && password[i+1] === password[i+2]) { hasRepeat = true; break; }
  }
  if (!hasRepeat) score += 5; else suggestions.push('Avoid repeating characters');

  if (!common.has(password.toLowerCase())) score += 10; else suggestions.push('Avoid common passwords');

  score = Math.min(100, Math.max(0, score));
  let strength;
  if (score <= 25) strength = 'very_weak';
  else if (score <= 50) strength = 'weak';
  else if (score <= 70) strength = 'medium';
  else if (score <= 90) strength = 'strong';
  else strength = 'very_strong';

  return { score, strength, suggestions };
}
